script.setup:
// meanderpy migrated a river centerline for 300 years (recipe meanderpy.migration →
// river.json). Every saved centerline and every cutoff (oxbow lake) becomes instanced
// segments tagged with its age; the shader shows only what exists at the replay time.
const data = await (await fetch(ctx.assets["river.json"])).json();
const gl = ctx.gl;
const items = [
  ...data.channels.map((c) => ({ ...c, kind: 0 })),
  ...data.cutoffs.map((c) => ({ ...c, kind: 1 })),
].sort((a, b) => a.age - b.age || b.kind - a.kind);
let count = 0;
for (const it of items) count += it.points.length / 2 - 1;
const inst = new Float32Array(count * 7);
let k = 0;
for (const it of items) {
  const p = it.points;
  let dist = 0;
  for (let i = 0; i + 3 < p.length; i += 2) {
    const len = Math.hypot(p[i + 2] - p[i], p[i + 3] - p[i + 1]);
    inst.set([p[i], p[i + 1], p[i + 2], p[i + 3], it.age, it.kind, dist], k * 7);
    dist += len; k++;
  }
}
// Frame the meandering stretch (the model keeps the upstream end straight).
let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
for (const c of data.channels) for (let i = 0; i < c.points.length; i += 2) {
  const x = c.points[i], y = c.points[i + 1];
  y0 = Math.min(y0, y); y1 = Math.max(y1, y);
  if (Math.abs(y) > 0.12) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); }
}
x0 -= 0.6; x1 += 0.6; y0 -= 0.4; y1 += 0.4;
const vao = gl.createVertexArray();
gl.bindVertexArray(vao);
gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([0, -1, 1, -1, 0, 1, 1, 1]), gl.STATIC_DRAW);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ARRAY_BUFFER, inst, gl.STATIC_DRAW);
[[1, 4, 0], [2, 1, 4], [3, 1, 5], [4, 1, 6]].forEach(([loc, size, off]) => {
  gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, size, gl.FLOAT, false, 28, off * 4); gl.vertexAttribDivisor(loc, 1);
});
gl.bindVertexArray(null);
const vs = `#version 300 es
layout(location=0) in vec2 a_corner; layout(location=1) in vec4 a_seg; layout(location=2) in float a_age; layout(location=3) in float a_kind; layout(location=4) in float a_dist;
uniform vec4 u_view; uniform float u_now; uniform float u_current; uniform float u_width; uniform float u_memory;
out float v_side; out float v_ago; out float v_kind; out float v_dist; out float v_current;
void main(){
  if (a_age > u_now + 1e-3) { gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return; }
  vec2 a = a_seg.xy, b = a_seg.zw, d = b - a; float len = max(length(d), 1e-5); vec2 dir = d / len, n = vec2(-dir.y, dir.x);
  float ago = u_now - a_age; bool current = a_kind < 0.5 && abs(a_age - u_current) < 1e-3;
  float w = u_width * (current ? 1.0 : a_kind > 0.5 ? mix(0.9, 0.6, clamp(ago / u_memory, 0.0, 1.0)) : 0.55);
  vec2 p = mix(a, b, a_corner.x) + dir * (a_corner.x * 2.0 - 1.0) * w * 0.5 + n * a_corner.y * w * 0.5;
  v_side = a_corner.y; v_ago = ago; v_kind = a_kind; v_dist = a_dist + a_corner.x * len; v_current = current ? 1.0 : 0.0;
  gl_Position = vec4((p - u_view.xy) * u_view.zw, 0.0, 1.0);
}`;
const fs = `#version 300 es
precision highp float; in float v_side; in float v_ago; in float v_kind; in float v_dist; in float v_current; out vec4 outColor;
uniform float u_time; uniform float u_memory; uniform vec3 u_water; uniform vec3 u_scroll;
void main(){
  float edge = 1.0 - v_side * v_side;
  float age = clamp(v_ago / u_memory, 0.0, 1.0);
  vec3 c; float a;
  if (v_current > 0.5) {
    float flow = 0.5 + 0.5 * sin(v_dist * 18.0 - u_time * 6.0);
    c = u_water * (0.75 + 0.35 * edge) + vec3(0.25) * flow * edge; a = 1.0;
  } else if (v_kind > 0.5) {
    c = mix(u_water * 0.75, vec3(0.16, 0.36, 0.34), age) * (0.7 + 0.3 * edge); a = mix(0.95, 0.55, age);
  } else {
    c = mix(u_scroll, vec3(0.22, 0.27, 0.17), sqrt(age)); a = mix(0.85, 0.35, age) * (0.6 + 0.4 * edge);
  }
  outColor = vec4(c * a, a);
}`;
Object.assign(ctx.state, {
  data, vao, count, bounds: [x0, x1, y0, y1],
  ages: data.channels.map((c) => c.age),
  p: ctx.utils.createProgram(vs, fs),
  bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform vec2 u_resolution;
float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(h(i), h(i + vec2(1, 0)), f.x), mix(h(i + vec2(0, 1)), h(i + vec2(1, 1)), f.x), f.y); }
void main(){ vec2 p = v_uv * u_resolution / u_resolution.y * 5.0; float n = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) { n += a * vn(p); p *= 2.03; a *= 0.5; }
  outColor = vec4(mix(vec3(0.055, 0.07, 0.05), vec3(0.1, 0.12, 0.08), n), 1.0); }`),
});
ctx.publish("centerlines", data.channels.length);
ctx.publish("oxbow lakes", data.cutoffs.length);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const end = s.ages[s.ages.length - 1], span = end / u.u_speed, hold = 3;
const t = ctx.time % (span + hold), now = Math.min(t / span, 1) * end;
let current = s.ages[0];
for (const a of s.ages) if (a <= now + 1e-3) current = a;
// Fit the meander belt to the canvas width; with zoom > 1 the mouse pans along the river.
const [x0, x1, y0, y1] = s.bounds;
const fitX = 2 / (x1 - x0), fitY = 2 / (y1 - y0) * h / w, k = Math.min(fitX, fitY) * u.u_zoom;
const halfW = 1 / k, cx = u.u_zoom > 1 ? x0 + halfW + (x1 - x0 - 2 * halfW) * ctx.mouse[0] : (x0 + x1) / 2;
const view = [cx, (y0 + y1) / 2, k, k * w / h];
ctx.utils.drawFullscreen(s.bg);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
gl.useProgram(s.p);
ctx.utils.setStandardUniforms(s.p);
ctx.utils.setUniforms(s.p, { u_view: view, u_now: now, u_current: current, u_width: s.data.width / 1000 * u.u_width, u_memory: u.u_memory });
gl.bindVertexArray(s.vao);
gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, s.count);
gl.bindVertexArray(null);
gl.disable(gl.BLEND);
ctx.publish("year", Math.round(now));
